function ATTAINED_AT_LEAST_TWICE(w[0..n-1], tol):
    if n == 0: return False
    m <- min(w)
    count <- 0
    for each value v in w:
        if |v - m| <= tol:
            count <- count + 1
            if count >= 2: return True
    return False

function TROP_EVAL(monomials, x):
    return min over (c, exp) in monomials of  c + sum_k exp[k]*x[k]

function TROP_MUL(P, Q):
    R <- empty list
    for (c1, e1) in P:
        for (c2, e2) in Q:
            R.append( (c1 + c2, e1 + e2 elementwise) )
    return R

function VERIFY_EVAL_MUL(P, Q, x, tol):
    return |TROP_EVAL(TROP_MUL(P,Q), x) - (TROP_EVAL(P,x)+TROP_EVAL(Q,x))| <= tol

