function ON_HYPERSURFACE(monomials, x, tol):
    vals <- [ c + <exp, x> for (c, exp) in monomials ]
    m <- min(vals)
    return (count of v in vals with |v - m| <= tol) >= 2

function IN_UNION(P, Q, x, tol):     # = membership in V(P (x) Q)
    return ON_HYPERSURFACE(P, x, tol) OR ON_HYPERSURFACE(Q, x, tol)
